"""Immutable inactivity-reminder values resolved from V1 parity evidence."""

import hashlib
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone

DEFAULT_INACTIVITY_THRESHOLD = timedelta(days=7)




def build_cycle_key(user_id: int, last_activity_at: datetime) -> str:
    """Create a stable cycle identity tied to the observed activity timestamp."""
    if not isinstance(user_id, int) or isinstance(user_id, bool) or user_id <= 0:
        raise ValueError("user_id_must_be_positive_integer")
    activity = normalize_utc(last_activity_at, "last_activity_at")
    payload = f"{user_id}:{activity.isoformat(timespec='microseconds')}".encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


@dataclass(frozen=True, slots=True)
class InactivityReminderDecision:
    """Pure evaluation result. It does not send, persist, retry, or schedule."""

    user_id: int
    last_activity_at: datetime
    evaluated_at: datetime
    due_at: datetime
    cycle_key: str
    due: bool
    already_delivered: bool


@dataclass(frozen=True, slots=True)
class InactivityReminderReceipt:
    """Persistent-audit payload for one successfully delivered cycle."""

    user_id: int
    cycle_key: str
    last_activity_at: datetime
    delivered_at: datetime

    def __post_init__(self) -> None:
        if not isinstance(self.user_id, int) or isinstance(self.user_id, bool) or self.user_id <= 0:
            raise ValueError("user_id_must_be_positive_integer")
        if not self.cycle_key.strip():
            raise ValueError("cycle_key_must_not_be_empty")
        object.__setattr__(self, "cycle_key", self.cycle_key.strip())
        object.__setattr__(self, "last_activity_at", normalize_utc(self.last_activity_at, "last_activity_at"))
        object.__setattr__(self, "delivered_at", normalize_utc(self.delivered_at, "delivered_at"))

# Source: service.py
"""Deterministic API-ready inactivity-reminder evaluation service."""

from datetime import datetime, timedelta



class InactivityReminderService:
    """Evaluate seven-full-day cycles without inventing scheduler/delivery policy."""

    def __init__(self, threshold: timedelta = DEFAULT_INACTIVITY_THRESHOLD) -> None:
        if threshold != DEFAULT_INACTIVITY_THRESHOLD:
            raise ValueError("unsupported_inactivity_threshold")
        self._threshold = threshold

    @property
    def threshold(self) -> timedelta:
        return self._threshold

    def evaluate(
        self,
        *,
        user_id: int,
        last_activity_at: datetime,
        evaluated_at: datetime,
        delivered_cycle_keys: frozenset[str] = frozenset(),
    ) -> InactivityReminderDecision:
        """Evaluate exactly one cycle from injected activity, clock and audit state."""
        activity = normalize_utc(last_activity_at, "last_activity_at")
        current = normalize_utc(evaluated_at, "evaluated_at")
        cycle_key = build_cycle_key(user_id, activity)
        due_at = activity + self._threshold
        delivered = cycle_key in delivered_cycle_keys
        return InactivityReminderDecision(
            user_id=user_id,
            last_activity_at=activity,
            evaluated_at=current,
            due_at=due_at,
            cycle_key=cycle_key,
            due=current >= due_at and not delivered,
            already_delivered=delivered,
        )

    def receipt_after_successful_delivery(
        self,
        decision: InactivityReminderDecision,
        *,
        delivered_at: datetime,
    ) -> InactivityReminderReceipt:
        """Build audit data only after an external adapter confirms delivery success."""
        if not decision.due or decision.already_delivered:
            raise ValueError("reminder_cycle_not_deliverable")
        delivered = normalize_utc(delivered_at, "delivered_at")
        if delivered < decision.due_at:
            raise ValueError("delivered_at_precedes_due_at")
        return InactivityReminderReceipt(
            user_id=decision.user_id,
            cycle_key=decision.cycle_key,
            last_activity_at=decision.last_activity_at,
            delivered_at=delivered,
        )

